toad_implementation.code_blueprint:
canvas {
  size: 800px 800px;
  fill: #080808;
  font-family: "VT323, monospace";
}

>crtBlack = #080808;
>shiftRed = #FF0055;
>shiftCyan = #00FFCC;
>scanline = #141414;

rect #baseGlitchBlockRed {
  at: center of canvas offset -6px 0px;
  size: 380px 220px;
  fill: alpha(>shiftRed, 0.60);
}

rect #baseGlitchBlockCyan {
  at: center of canvas offset 6px 0px;
  size: 380px 220px;
  fill: alpha(>shiftCyan, 0.60);
}

rect #baseGlitchCore {
  at: center of canvas;
  size: 380px 220px;
  fill: #111111;
  stroke: #FFFFFF;
  stroke-width: 2px;
}

text #glitchTextRed {
  at: center of #baseGlitchCore offset -4px -2px;
  content: "S Y S T E M _ F A I L";
  font-size: 36px;
  font-weight: 700;
  color: >shiftRed;
}

text #glitchTextCyan {
  at: center of #baseGlitchCore offset 4px 2px;
  content: "S Y S T E M _ F A I L";
  font-size: 36px;
  font-weight: 700;
  color: >shiftCyan;
}

text #glitchTextWhite {
  at: center of #baseGlitchCore;
  content: "S Y S T E M _ F A I L";
  font-size: 36px;
  font-weight: 700;
  color: #FFFFFF;
}

text #crtFooter {
  at: bottom left of canvas offset 40px -40px;
  content: "SIGNAL: ANALOG NTSC • ERR_CODE: 0x7E • VCR SYNC";
  font-size: 16px;
  color: >shiftCyan;
}
